import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"人生目标","description":"人一生只有一个主线任务","frontmatter":{"title":"人生目标","description":"人一生只有一个主线任务","date":"2026-05-29T00:00:00.000Z","category":"生活指南","tags":["人生主线"],"order":1},"headers":[],"relativePath":"articles/life/life-plan/keypoint.md","filePath":"articles/life/life-plan/keypoint.md","articleMeta":{"updated":"2026-05-29","words":334,"minutes":1}}`),a={name:`articles/life/life-plan/keypoint.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>人一生只有一个主线任务：内心的平静、 深度的人际关系、专业上的精通，以及一种与自身价值观高度一致的生活方式。</p><p>成事者意识到，值得优先考虑的是那些由自然规律决定、上限被锁死的资源，比如<strong>时间</strong>，比如情绪，比如注意力，</p><p>可以将这些资源统称为心智资源，每人每天的有效心智资源有限，具体表现在高度专注工作时长无法超过4小时，</p><p>于是他们会从时间成本的角度做决策，如果做某件事外包的成本低于时薪，那就外包；如果不做的损失低于时薪，那就不做；如果花钱请人的成本低于时薪，那就花钱请人。</p><p>更进一步，即使在年轻尚未富有时，成事者便开始遵循<strong>注意力＞时间＞金钱</strong>的决策逻辑，大胆地为自己设定一个很高的时薪，并坚持执行。</p><p>是关系、人脉、能力，使你爬上了领导岗位。</p><p>而不是领导岗位赋予你关系和能力。</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};